// Verbum — Latin 101 curriculum (Henle *First Year Latin*, Units 1–2)
// Data-only file. Interfaces and helpers are the app's public contract —
// do not rename exports used by src/routes/lessons/latin.tsx, drillUtils, etc.
export interface VocabularyItem { latin:string; english:string; pronunciation?:string; gender?:string; type?:string }
export interface MultipleChoiceExercise { type:"multiple-choice"; id:string; prompt:string; options:string[]; correctIndex:number; explanation?:string }
export interface FillInBlankExercise { type:"fill-in-blank"; id:string; prompt:string; before?:string; after?:string; answer:string; acceptableAnswers?:string[]; explanation?:string }
export interface MatchingPair { left:string; right:string; pronunciation?:string }
export interface MatchingExercise { type:"matching"; id:string; prompt:string; leftLabel?:string; rightLabel?:string; pairs:MatchingPair[] }
export interface FlashcardExercise { type:"flashcard"; id:string; prompt:string; front:string; back:string; hint?:string }
/** A comprehension question inside a reading passage — reuses the MC and fill-in-blank checks. */
export type ReadingPassageQuestion=MultipleChoiceExercise|FillInBlankExercise;
export interface ReadingPassageExercise { type:"reading-passage"; id:string; title:string; passage:string; passageLines?:string[]; glosses?:VocabularyItem[]; translation?:string; source?:string; revealLines?:boolean; questions:ReadingPassageQuestion[]; passThreshold?:number; explanation?:string }
export type CultureDomain = "history" | "customs" | "context";
export interface CultureQuestionExercise { type:"culture-question"; id:string; prompt:string; options:string[]; correctIndex:number; explanation:string; source:string; domain:CultureDomain }
export type Exercise=MultipleChoiceExercise|FillInBlankExercise|MatchingExercise|FlashcardExercise|ReadingPassageExercise|CultureQuestionExercise;
export interface Lesson { id:number; title:string; subtitle?:string; concept:string; conceptHtml?:string; referenceTable?:{title:string;headers:string[];rows:string[][];highlightRows?:number[]}; vocabularyTable?:{title:string;headers:string[];rows:string[][]}; vocabulary?:VocabularyItem[]; exercises:Exercise[]; teachingSteps?:TeachingStep[]; comprehensionCheck?:ComprehensionQuestion[]; conjugationTable?:ConjugationTable }

export interface TeachingStep {
  title: string;
  explanation: string;
  exampleLatin: string;
  exampleEnglish: string;
  tip?: string;
  /** GrammarTopic ids (src/data/grammarIndex.ts) this step teaches — links the
   *  step to the Grammar Index; renderers resolve id → topic → henleGrammarRef. */
  grammarRefs?: string[];
}

export interface ConjugationRow {
  person: string;
  singular: string;
  plural: string;
}

export interface ConjugationTable {
  title: string;
  tenseVoice: string;
  headers: string[];
  rows: ConjugationRow[];
}

export interface ComprehensionQuestion {
  question: string;
  options: string[];
  correctIndex: number;
  explanation: string;
}
const mc=(id:string,prompt:string,options:string[],correctIndex:number,explanation?:string):MultipleChoiceExercise=>({type:"multiple-choice",id,prompt,options,correctIndex,explanation});
const fill=(id:string,prompt:string,answer:string,acceptableAnswers:string[]=[],explanation?:string):FillInBlankExercise=>({type:"fill-in-blank",id,prompt,answer,acceptableAnswers,explanation});
const match=(id:string,prompt:string,pairs:MatchingPair[]):MatchingExercise=>({type:"matching",id,prompt,pairs});
const words=(items:[string,string,string?][]):VocabularyItem[]=>items.map(([latin,english,pronunciation])=>({latin,english,pronunciation}));
const w=(latin:string,english:string,pronunciation:string,gender?:string,type?:string):VocabularyItem=>({latin,english,pronunciation,gender,type});
const mp=(left:string,right:string):MatchingPair=>({left,right});
const vt=(title:string,items:VocabularyItem[])=>({title,headers:["Latin","English"],rows:items.map(i=>[i.latin,i.english])});

