teachingSteps:[
  {title:"The Genitive Singular Names the Declension",explanation:"The General Review drill asks for four things about each noun — genitive singular, gender, meaning, and ablative singular — and the genitive singular comes first because it identifies the declension: -is marks the third declension (gentis, arcis, partis), -ae the first (morae, grātiae), -ī the second (iugī, pagī), -ūs the fourth (mōtūs), and -ēī the fifth (diēī).",exampleLatin:"gēns, gentis · mora, morae · iugum, iugī",exampleEnglish:"clan · delay · yoke — three declensions, one drill",tip:"Say the genitive singular out loud with the noun every time you review it.",grammarRefs:["third-declension","first-declension","second-declension"]},
  {title:"The i-Stems Hide in the Genitive Plural",explanation:"Many nouns in this list are i-stems: their genitive plural keeps an -i- (partium, hostium, arcium, urbium). The genitive plural is where the i-stem family shows itself — pars, hostis, arx, urbs, turris, classis, gēns, mors, collis, mēnsis, cliēns, adulēscēns, linter all belong to it, while vulnus, tempus, magnitūdō and the rest keep plain -um.",exampleLatin:"pars, partium · hostis, hostium · tempus, temporum",exampleEnglish:"of the parts · of the enemies · of the times",tip:"If the genitive singular ends -is or -e, suspect an i-stem — check the genitive plural.",grammarRefs:["third-declension-i-stems","third-declension"]},
  {title:"Not a Third-Declension List Only",explanation:"Henle mixes review into the drill: iugum, iumentum, pagus, vallum are second declension; mora, grātia, vigilia are first; mōtus is fourth; rēs and diēs are fifth. The ablative singular follows each noun's own declension: iugō, morā, mōtū, rē.",exampleLatin:"in iugō · morā · mōtū · rē",exampleEnglish:"in the yoke · in the delay · in the movement · in the matter",tip:"The ablative singular is your quick check that you know the whole declension, not just the genitive.",grammarRefs:["fourth-declension","fifth-declension","first-declension"]}
],
comprehensionCheck:[
  {question:"What is the genitive singular of mōns?",options:["montis","montī","montem","montium"],correctIndex:0,explanation:"mōns, montis — the genitive singular is montis; the ablative singular is montī, the accusative montem."},
  {question:"Which of these is NOT a third-declension noun?",options:["mora","arx","tempus","hostis"],correctIndex:0,explanation:"mora, morae is first declension. arx, tempus, and hostis are third declension."},
  {question:"Which noun has the genitive plural mōtuum?",options:["mōtus","mōns","mors","mēnsis"],correctIndex:0,explanation:"mōtus is fourth declension: genitive plural mōtuum. mōns, mors, and mēnsis are third declension (-ium for mōns and mēnsis, mortium for mors)."}
],
