teachingSteps:[
  {title:"The Third Principal Part Carries the Perfect",explanation:"Every tense of the perfect system — perfect, pluperfect, future perfect — grows from the third principal part: necō, necāre, necāvī gives necāvī, necāveram, necāverō. The drill shows the first two parts and asks you to produce the third from memory, exactly as the review specifies: give the principal parts, then the meaning.",exampleLatin:"vincō, vincere, vīcī, victus",exampleEnglish:"I conquer — perfect stem vīc-",tip:"Say all four parts in rhythm; the 3rd is the one the perfect system lives on.",grammarRefs:["principal-parts","perfect-system-active"]},
  {title:"Reading the First Two Parts",explanation:"The first part (1st-person singular present) and the second (present infinitive) tell you the conjugation: -āre = 1st (necō, necāre), -ēre = 2nd (habeō, habēre), -ere = 3rd (dūcō, dūcere), -īre = 4th (audiō, audīre). The archive prints many of these first parts with a stray S (ostendS, habeS) — restored mechanically to -ō throughout.",exampleLatin:"ostendō, ostendere · audiō, audīre",exampleEnglish:"third conjugation · fourth conjugation",tip:"Conjugation tells you the pattern of the 3rd principal part — but the exact vowel change is memory work.",grammarRefs:["principal-parts","first-and-second-conjugations","third-conjugation","fourth-conjugation"]},
  {title:"Verbs Without a Fourth Part",explanation:"Several verbs in the list have no fourth principal part (incolō, perveniō, sustineō, praecedō): they live entirely on three parts. The drill asks only for the third — but know that a missing fourth part is information, not an omission.",exampleLatin:"incolō, incolere, incoluī — (no fourth part)",exampleEnglish:"I inhabit, to inhabit, I inhabited",tip:"If a verb has no perfect participle, it usually paraphrases with another verb.",grammarRefs:["principal-parts"]}
],
comprehensionCheck:[
  {question:"The third principal part of habēre (2nd conj.) is…",options:["habuī","habeō","habitum","habēbam"],correctIndex:0,explanation:"habeō, habēre, habuī, habitus — the perfect is habuī, the stem the perfect system builds on."},
  {question:"Which verb's third principal part has a -x- (from -c- + -s-)?",options:["dūcō → dūxī","teneō → tenuī","regō → rēxī","pōnō → posuī"],correctIndex:0,explanation:"dūcō, dūcere, dūxī, ductus — the -c- before -s- spells -x-. regō gives rēxī too; pōnō gives posuī (suppletive)."},
  {question:"dō, dare, dedī, datus is what kind of verb?",options:["First-conjugation-like with short -a- (irregular)","Second conjugation","Third conjugation","Deponent"],correctIndex:0,explanation:"dō declines like a first-conjugation verb but keeps short -a- (dare, daturus): dedī, datus — Henle lists it among the irregulars."}
],
